package com.scalar.db.nativejdbc.samples.jpa;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import org.jspecify.annotations.Nullable;

/**
 * An item, its key generated by the database, its version checked on every update. The names are
 * unquoted, so that the database spells them as it stores them: upper case on Oracle. The table's
 * is given in lower case, as it was created, for MySQL, whose table names are case-sensitive.
 */
@Entity
@Table(name = "item")
public class Item {
  @Id
  @GeneratedValue(strategy = GenerationType.IDENTITY)
  private @Nullable Long id;

  private String name = "";
  private int qty;
  @Version private @Nullable Integer version;

  /** For Hibernate, which makes an entity before it sets its fields. */
  protected Item() {}

  public Item(String name, int qty) {
    this.name = name;
    this.qty = qty;
  }

  public @Nullable Long getId() {
    return id;
  }

  public String getName() {
    return name;
  }

  public void setName(String name) {
    this.name = name;
  }

  public int getQty() {
    return qty;
  }

  public void setQty(int qty) {
    this.qty = qty;
  }

  public @Nullable Integer getVersion() {
    return version;
  }
}
